        expect(screen.getByRole('button', { name: 'One' })).toHaveAttribute('data-diagram-node-shape', 'ellipse')
    })

    it('renders and resizes a decision inside unchanged rectangular bounds', () => {
        const node = positioned({ height: 96, kind: 'decision', label: 'Choose', width: 96 })
        const { rerender } = render(
            <ThemeProvider theme={createAppTheme('dark')}>
                <DiagramNode diagramType="flow" flowPreset="flowchart" node={node} onSelect={vi.fn()} selected={false} />
            </ThemeProvider>,
        )
        const button = screen.getByRole('button', { name: 'Choose' })
        const diamond = button.querySelector('[data-diagram-node-shape="decision"]')

        expect(getComputedStyle(button).height).toBe('96px')
        expect(getComputedStyle(button).width).toBe('96px')
        expect(getComputedStyle(button).transform).toBe('none')
        expect(diamond).toHaveAttribute('viewBox', '0 0 96 96')

        rerender(
            <ThemeProvider theme={createAppTheme('dark')}>
                <DiagramNode
                    diagramType="flow"
                    flowPreset="flowchart"
                    node={{ ...node, height: 80, width: 120 }}
                    onSelect={vi.fn()}
                    selected={false}
                />
            </ThemeProvider>,
        )

        expect(getComputedStyle(button).height).toBe('80px')
        expect(getComputedStyle(button).width).toBe('120px')
        expect(button.querySelector('[data-diagram-node-shape="decision"]')).toHaveAttribute('viewBox', '0 0 120 80')
    })

    it('reports Ctrl state for clicks and treats keyboard activation as plain selection', async () => {
        const { button, onSelect } = renderNode(positioned())
        const user = userEvent.setup()

        await user.click(button)
        expect(onSelect).toHaveBeenCalledWith(expect.objectContaining({ id: 'one', label: 'One' }), false)

        onSelect.mockClear()
        fireEvent.click(button, { ctrlKey: true })
        expect(onSelect).toHaveBeenCalledWith(expect.objectContaining({ id: 'one', label: 'One' }), true)

        onSelect.mockClear()
        button.focus()
        await user.keyboard('{Enter}')
        expect(onSelect).toHaveBeenCalledWith(expect.objectContaining({ id: 'one', label: 'One' }), false)
    })

    it('does not select the node when the content scrolled between mousedown and click', () => {
        const { button, onSelect } = renderNode(positioned({ sublabel: 'long enough to scroll' }))
        const wrapper = scrollWrapper(button) as HTMLElement

        fireEvent.mouseDown(button)
        wrapper.scrollTop = 24
        fireEvent.click(button)

        expect(onSelect).not.toHaveBeenCalled()
    })

    it('keeps non-drilldown node content scrollable and allows selection', async () => {
        const { button, onSelect } = renderNode(positioned({ drilldown: false, sublabel: 'long enough to scroll' }))
        const wrapper = scrollWrapper(button) as HTMLElement
        const user = userEvent.setup()

        expect(button).toHaveAttribute('aria-pressed', 'false')
        expect(button).toHaveAttribute('tabindex', '0')
        expect(button).not.toBeDisabled()
        expect(getComputedStyle(wrapper).overflowY).toBe('auto')

        await user.click(wrapper)
        fireEvent.keyDown(button, { key: 'Enter' })

        expect(onSelect).toHaveBeenCalledTimes(2)
    })
})

import MoreHorizOutlined from '@mui/icons-material/MoreHorizOutlined'
import { Box, IconButton, TextField, Tooltip } from '@mui/material'
import { useState, type ChangeEvent, type KeyboardEvent, type MouseEvent, type PointerEvent } from 'react'
import type { DiagramEditSessionService } from '../../../services/diagrams/diagram_edit_session_service'
import type { PositionedDiagramNode } from '../../../services/diagrams/diagram_layout'

/** Inline label and details action above one editable node. */
export function DiagramInlineNodeControls({ node, onOpenDetails, session }: {
    node: PositionedDiagramNode
    onOpenDetails: () => void
    session: DiagramEditSessionService
}) {
    const [draftState, setDraftState] = useState({ base: node.label, value: node.label })
    const draft = draftState.base === node.label ? draftState.value : node.label
    const [error, setError] = useState<string | null>(null)
    const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
        setDraftState({ base: node.label, value: event.target.value })
        setError(null)
    }
    const commit = () => {
        if (draft.trim() === node.label) return
        if (!draft.trim()) {
            setError('Label is required.')

            return
        }
        if (!session.setNodeField(node.id, 'label', draft.trim())) setError('Label could not be saved.')
    }
    const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
        if (event.key === 'Escape') {
            event.stopPropagation()
            setDraftState({ base: node.label, value: node.label })
            setError(null)

            return
        }
        if (event.key !== 'Enter') return
        event.preventDefault()
        commit()
    }
    const stopPointer = (event: PointerEvent<HTMLElement>) => {
        if (session.getActiveToolSnapshot().startsWith('edge:')) return
        event.stopPropagation()
    }
    const stopClick = (event: MouseEvent<HTMLElement>) => event.stopPropagation()
    const handleDoubleClick = (event: MouseEvent<HTMLElement>) => {
        event.stopPropagation()
        onOpenDetails()
    }

    return (
        <Box
            className="diagram-node-inline-controls"
            data-diagram-connection-target={node.id}
            onClick={stopClick}
            onDoubleClick={handleDoubleClick}
            onPointerDown={stopPointer}
            sx={{
                height: node.height, left: node.x, pointerEvents: 'none', position: 'absolute', top: node.y,
                width: node.width, zIndex: 3,
                '& .diagram-node-details-action': { opacity: 0 },
                '&:hover .diagram-node-details-action, &:focus-within .diagram-node-details-action': { opacity: 1 },
                '@media (hover: none)': { '& .diagram-node-details-action': { opacity: 1 } },
            }}
        >
            <TextField
                error={!!error}
                helperText={error}
                onBlur={commit}
                onChange={handleChange}
                onKeyDown={handleKeyDown}
                size="small"
                slotProps={{ htmlInput: { 'aria-label': `Edit ${node.label} label` } }}
                sx={{
                    left: '50%', maxWidth: 'calc(100% - 48px)', pointerEvents: 'auto', position: 'absolute',
                    top: '50%', transform: 'translate(-50%, -50%)',
                    '& .MuiInputBase-root': { bgcolor: 'transparent' },
                    '& .MuiInputBase-input': { textAlign: 'center' },
                }}
                value={draft}
                variant="standard"
            />
            <Tooltip title={`Details for ${node.label}`}>
                <IconButton
                    aria-label={`Details for ${node.label}`}
                    className="diagram-node-details-action"
                    onClick={onOpenDetails}
                    size="small"
                    sx={{ pointerEvents: 'auto', position: 'absolute', right: 2, top: 2 }}
                >
                    <MoreHorizOutlined fontSize="small" />
                </IconButton>
            </Tooltip>
        </Box>
    )
}

import { useEffect, useState } from 'react'
import type { DiagramEdgeKind, DiagramRole } from '../../../services/diagrams/diagram_data'
import {
    diagramEditSessionService, type DiagramEditSessionService,
} from '../../../services/diagrams/diagram_edit_session_service'
import { derivedDiagramLegendEntries, type DiagramLegendEntry } from './diagram_legend_entries'
import { DiagramLegendEntryList } from './diagram_legend_entry_list'

export type SessionLegendSource = DiagramEditSessionService

function explicitEntries(session: SessionLegendSource, entryKeys: readonly string[]): DiagramLegendEntry[] {
    return entryKeys.flatMap((entryKey): DiagramLegendEntry[] => {
        const label = session.getLegendEntryFieldSnapshot(entryKey, 'label')
        if (label === null) return []
        const role = session.getLegendEntryFieldSnapshot(entryKey, 'role')
        if (role !== null) return [{ entryType: 'node', label, role: role as DiagramRole }]
        const kind = session.getLegendEntryFieldSnapshot(entryKey, 'kind')

        return kind === null ? [] : [{ entryType: 'connection', kind: kind as DiagramEdgeKind, label }]
    })
}

function sessionEntries(session: SessionLegendSource): DiagramLegendEntry[] {
    const entryKeys = session.getLegendEntryKeysSnapshot()
    if (session.getHasExplicitLegendSnapshot()) return explicitEntries(session, entryKeys)

    const roles = session.getNodeIdsSnapshot()
        .map((nodeId) => session.getNodeFieldSnapshot(nodeId, 'role'))
        .filter((role): role is DiagramRole => role !== null)
    const kinds = session.getEdgeIdsSnapshot()
        .map((edgeId) => session.getEdgeFieldSnapshot(edgeId, 'kind'))
        .filter((kind): kind is DiagramEdgeKind => kind !== null)

    return derivedDiagramLegendEntries(roles, kinds)
}

/**
 * Subscribes to explicit legend membership and each entry's own label, falling back to the semantics
 * of the edited nodes and edges while the diagram carries no explicit entries. Never reads a complete
 * diagram or legend snapshot.
 */
function useSessionLegendEntries(session: SessionLegendSource) {
    const [entries, setEntries] = useState(() => sessionEntries(session))
    const [membershipVersion, setMembershipVersion] = useState(0)

    useEffect(() => {
        const onMembershipChange = () => {
            setEntries(sessionEntries(session))
            setMembershipVersion((version) => version + 1)
        }
        onMembershipChange()
        const unsubscribes = [
            session.subscribeSession(onMembershipChange),
            session.subscribeLegendMembership(onMembershipChange),
            session.subscribeCollectionMembership('node', onMembershipChange),
            session.subscribeCollectionMembership('edge', onMembershipChange),
        ]

        return () => {
            for (const unsubscribe of unsubscribes) unsubscribe()
        }
    }, [session])

    useEffect(() => {
        const refresh = () => setEntries(sessionEntries(session))
        const displayedKeys = sessionEntries(session).map((entry) => (
            entry.entryType === 'node' ? `node:${entry.role}` : `connection:${entry.kind}`
        ))
        const unsubscribes = [
            ...displayedKeys.map((entryKey) => session.subscribeLegendEntryField(entryKey, 'label', refresh)),
            ...session.getNodeIdsSnapshot().map((nodeId) => session.subscribeNodeField(nodeId, 'role', refresh)),
            ...session.getEdgeIdsSnapshot().map((edgeId) => session.subscribeEdgeField(edgeId, 'kind', refresh)),
        ]

        return () => {
            for (const unsubscribe of unsubscribes) unsubscribe()
        }
    }, [membershipVersion, session])

    return entries
}

/** Legend body describing the New diagram of the active edit session. */
export function DiagramSessionLegendEntries({
    label = 'New diagram legend entries',
    session = diagramEditSessionService,
}: {
    label?: string
    session?: SessionLegendSource
}) {
    return <DiagramLegendEntryList entries={useSessionLegendEntries(session)} label={label} session={session} store={session} />
}

import { Box, Typography } from '@mui/material'
import { useRef, type MouseEvent } from 'react'
import type { PositionedDiagramData } from '../../../services/diagrams/diagram_layout'
import { DiagramGroup } from './diagram_group'
import type { DiagramSelectHandler, DiagramSelection } from '../editing/diagram_selection'
import { SequenceActivation } from './sequence_activation'
import { SequenceFragment } from './sequence_fragment'
import { diagramViewService, type DiagramViewService } from '../../../services/diagrams/diagram_view_service'
import { CurrentDiagramEdge } from './current_diagram_edge'
import { CurrentDiagramNode } from './current_diagram_node'
import { diagramEmphasisService, type DiagramEmphasisService } from '../../../services/diagrams/diagram_emphasis_service'
import { SequenceLifeline } from './sequence_lifeline'
import { diagramFontStyle } from '../formatting/diagram_font_style'
import { useDiagramFormattingScale } from '../formatting/use_diagram_formatting'

export interface DiagramProps {
    circularNodes?: boolean
    curvedEdges?: boolean
    data: PositionedDiagramData
    emphasis?: DiagramEmphasisService
    onContextMenu?: (anchorElement: HTMLElement, selection: DiagramSelection) => void
    onSelect: (anchorElement: HTMLElement, selection: DiagramSelection) => void
    service?: Pick<DiagramViewService, 'getCurrentSelectionSnapshot' | 'subscribeCurrentSelection'>
}

/** Default context handler for isolated renderer use. */
function ignoreContextMenu() {}

/** Diagram surface composed from validated semantic data and positioned React children. */
export function Diagram(props: DiagramProps) {
    const {circularNodes = false, curvedEdges = false, data, emphasis = diagramEmphasisService} = props
    const {onContextMenu = ignoreContextMenu} = props
    const {onSelect, service = diagramViewService} = props
    const fontScalePercent = useDiagramFormattingScale('fontScalePercent', service as DiagramViewService)
    const surfaceRef = useRef<HTMLDivElement>(null)
    const nodeLabels = new Map(data.nodes.map((node) => [node.id, node.label]))
    const handleSelect: DiagramSelectHandler = (selection) => {
        if (surfaceRef.current) onSelect(surfaceRef.current, selection)
    }
    const handleContextMenu = (event: MouseEvent<HTMLDivElement>) => {
        const objectElement = (event.target as Element).closest<HTMLElement>('[data-diagram-id][data-diagram-kind]')
        const objectKind = objectElement?.dataset.diagramKind
        if (!objectElement || (objectKind !== 'edge' && objectKind !== 'node')) return
        event.preventDefault()
        const id = objectElement.dataset.diagramId
        const label = objectElement.getAttribute('aria-label')
        if (!id || !label) throw new Error('Diagram context target is missing identity or label')
        onContextMenu(event.currentTarget, { id, label, left: event.clientX, objectKind, top: event.clientY })
    }
    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5, minWidth: data.width }}>
            <Box sx={{ bgcolor: 'background.default', left: 0, position: 'sticky', top: 0, width: 'fit-content', zIndex: 5 }}>
                <Typography sx={diagramFontStyle(undefined, fontScalePercent, 'h6')} variant="h6">{data.meta.title}</Typography>
                <Typography
                    color="text.secondary"
                    sx={diagramFontStyle(undefined, fontScalePercent, 'body2')}
                    variant="body2"
                >
                    {data.meta.description}
                </Typography>
            </Box>
            <Box
                aria-label={`${data.meta.title} diagram`}
                onContextMenu={handleContextMenu}
                ref={surfaceRef}
                sx={{ height: data.height, position: 'relative', width: data.width }}
            >
                <Box sx={{ height: data.height - data.originY, left: data.originX, position: 'absolute', top: data.originY, width: data.width - data.originX }}>
                    {data.groups.map((group) => (
                        <DiagramGroup
                            emphasis={emphasis}
                            formattingStore={service as DiagramViewService}
                            group={group}
                            key={group.id}
                        />
                    ))}
                    {data.fragments.map((fragment) => (
                        <SequenceFragment
                            emphasis={emphasis}
                            formattingStore={service as DiagramViewService}
                            fragment={fragment}
                            key={fragment.id}
                        />
                    ))}
                    {data.meta.type === 'sequence' ? data.nodes.map((node) => (
                        <SequenceLifeline
                            emphasis={emphasis}
                            height={data.height - data.originY - 24 - node.y - node.height}
                            key={`sequence-${node.id}`}
                            nodeId={node.id}
                            x={node.x + node.width / 2}
                            y={node.y + node.height}
                        />
                    )) : null}
                    {data.activations.map((activation) => (
                        <SequenceActivation activation={activation} emphasis={emphasis} key={activation.id} />
                    ))}
                    <svg aria-label="Diagram connections" height={data.height - data.originY} style={{ left: 0, overflow: 'visible', position: 'absolute', top: 0, zIndex: 1 }} width={data.width - data.originX}>
                        {data.edges.map((edge) => (
                            <CurrentDiagramEdge
                                curved={curvedEdges}
                                edge={edge}
                                emphasis={emphasis}
                                key={edge.id}
                                nodeLabels={nodeLabels}
                                onSelect={handleSelect}
                                service={service}
                            />
                        ))}
                    </svg>
                    {data.nodes.map((node) => (
                        <CurrentDiagramNode
                            circular={circularNodes}
                            diagramType={data.meta.type}
                            emphasis={emphasis}
                            flowPreset={data.meta.preset}
                            key={node.id}
                            node={node}
                            onSelect={handleSelect}
                            service={service}
                        />
                    ))}
                </Box>
            </Box>
        </Box>
    )
}

